/**
 * Downloads S&P 500 (^GSPC) daily closes from Yahoo Finance (no API key).
 * Run at build time so the static site avoids browser CORS to Yahoo.
 */
import { mkdir, writeFile } from 'node:fs/promises'
import { dirname, join } from 'node:path'
import { fileURLToPath } from 'node:url'

const __dirname = dirname(fileURLToPath(import.meta.url))
const outPath = join(__dirname, '..', 'public', 'gspc.json')

const RANGE = '5y'
const URL = `https://query1.finance.yahoo.com/v8/finance/chart/%5EGSPC?interval=1d&range=${RANGE}`

async function main() {
  const res = await fetch(URL, {
    headers: {
      'User-Agent':
        'Mozilla/5.0 (compatible; SP500StaticChart/1.0; +https://example.local)',
      Accept: 'application/json',
    },
  })
  if (!res.ok) {
    throw new Error(`Yahoo chart request failed: ${res.status} ${res.statusText}`)
  }
  const j = await res.json()
  const result = j?.chart?.result?.[0]
  if (!result) {
    throw new Error('Unexpected Yahoo response: missing chart.result[0]')
  }
  const ts = result.timestamp ?? []
  const closes = result.indicators?.quote?.[0]?.close ?? []
  const series = []
  for (let i = 0; i < ts.length; i++) {
    const c = closes[i]
    if (c == null || Number.isNaN(c)) continue
    const tSec = ts[i]
    series.push({
      t: new Date(tSec * 1000).toISOString().slice(0, 10),
      c: Number(c),
    })
  }
  const meta = result.meta ?? {}
  const payload = {
    symbol: meta.symbol ?? '^GSPC',
    name: meta.longName ?? meta.shortName ?? 'S&P 500',
    range: RANGE,
    updatedAt: new Date().toISOString(),
    series,
  }
  await mkdir(dirname(outPath), { recursive: true })
  await writeFile(outPath, JSON.stringify(payload), 'utf8')
  console.log(`Wrote ${series.length} points to public/gspc.json`)
}

main().catch((e) => {
  console.error(e)
  process.exit(1)
})

import * as d3 from 'd3'
import { useEffect, useRef, useState } from 'react'

export type GspcPoint = { t: string; c: number }

export type GspcPayload = {
  symbol: string
  name: string
  range: string
  updatedAt: string
  series: GspcPoint[]
}

type Margin = { top: number; right: number; bottom: number; left: number }

function parseSeries(payload: GspcPayload) {
  return payload.series.map((d) => ({
    date: new Date(d.t + 'T12:00:00'),
    close: d.c,
  }))
}

export function Sp500Chart() {
  const wrapRef = useRef<HTMLDivElement>(null)
  const [payload, setPayload] = useState<GspcPayload | null>(null)
  const [loadError, setLoadError] = useState<string | null>(null)

  useEffect(() => {
    let cancelled = false
    ;(async () => {
      try {
        const res = await fetch('/gspc.json')
        if (!res.ok) throw new Error(`${res.status} ${res.statusText}`)
        const j = (await res.json()) as GspcPayload
        if (!cancelled) setPayload(j)
      } catch (e) {
        if (!cancelled)
          setLoadError(e instanceof Error ? e.message : 'Failed to load data')
      }
    })()
    return () => {
      cancelled = true
    }
  }, [])

  useEffect(() => {
    if (!payload?.series?.length || !wrapRef.current) return

    const data = parseSeries(payload)
    const margin: Margin = { top: 16, right: 24, bottom: 112, left: 56 }
    const contextHeight = 72
    const focusRatio = 0.72

    const container = wrapRef.current
    const svg = d3.select(container).select('svg')
    svg.selectAll('*').remove()

    const ro = new ResizeObserver(() => draw())
    ro.observe(container)

    function draw() {
      if (!wrapRef.current) return
      const width = wrapRef.current.clientWidth
      const totalH = Math.max(360, Math.round(width * 0.55))
      const focusH = Math.round(totalH * focusRatio)
      const innerW = width - margin.left - margin.right
      const innerFocusH = focusH - margin.top - 24
      const contextTop = margin.top + innerFocusH + 32
      const innerCtxH = contextHeight - 18

      svg.attr('width', width).attr('height', totalH)

      const xFull = d3
        .scaleTime()
        .domain(d3.extent(data, (d) => d.date) as [Date, Date])
        .range([0, innerW])

      const yFull = d3
        .scaleLinear()
        .domain([d3.min(data, (d) => d.close)! * 0.98, d3.max(data, (d) => d.close)! * 1.02])
        .nice()
        .range([innerCtxH, 0])

      let brushDomain = xFull.domain() as [Date, Date]

      const gRoot = svg.append('g').attr('transform', `translate(${margin.left},${margin.top})`)

      const clipId = `clip-${Math.random().toString(36).slice(2)}`
      gRoot
        .append('defs')
        .append('clipPath')
        .attr('id', clipId)
        .append('rect')
        .attr('width', innerW)
        .attr('height', innerFocusH)

      const gFocus = gRoot.append('g')
      const gFocusChart = gFocus.append('g').attr('clip-path', `url(#${clipId})`)

      const gxFocus = gFocus.append('g').attr('transform', `translate(0,${innerFocusH})`)
      const gyFocus = gFocus.append('g')

      const gCtx = gRoot.append('g').attr('transform', `translate(0,${contextTop})`)
      const gCtxPath = gCtx.append('g')
      const gxCtx = gCtx.append('g').attr('transform', `translate(0,${innerCtxH})`)
      const brushG = gCtx.append('g').attr('class', 'brush')

      const tooltip = d3
        .select(container)
        .append('div')
        .attr('class', 'sp5-tooltip')
        .style('position', 'absolute')
        .style('pointer-events', 'none')
        .style('opacity', 0)
        .style('top', 0)
        .style('left', 0)

      const lineFull = d3
        .line<{ date: Date; close: number }>()
        .x((d) => xFull(d.date))
        .y((d) => yFull(d.close))

      gCtxPath
        .append('path')
        .datum(data)
        .attr('fill', 'none')
        .attr('stroke', 'var(--chart-muted)')
        .attr('stroke-width', 1.25)
        .attr('d', lineFull)

      const xAxisCtx = d3.axisBottom(xFull).ticks(6).tickSizeOuter(0)
      gxCtx.call(xAxisCtx).call((g) => g.select('.domain').attr('stroke', 'var(--border)'))

      const brush = d3
        .brushX()
        .extent([
          [0, 0],
          [innerW, innerCtxH],
        ])
        .on('end', (event) => {
          const sel = event.selection as [number, number] | null
          if (!event.sourceEvent) return
          if (!sel) {
            brushDomain = xFull.domain() as [Date, Date]
          } else {
            brushDomain = [xFull.invert(sel[0]), xFull.invert(sel[1])]
          }
          updateFocus()
        })

      brushG.call(brush).call(brush.move, [0, innerW])

      const bisect = d3.bisector<{ date: Date; close: number }, Date>((d) => d.date).center

      const focusOverlay = gFocus
        .append('rect')
        .attr('width', innerW)
        .attr('height', innerFocusH)
        .attr('fill', 'transparent')
        .style('cursor', 'crosshair')

      const hoverG = gFocus.append('g').style('display', 'none')
      const hoverLine = hoverG.append('line').attr('stroke', 'var(--accent)').attr('stroke-dasharray', '4 4')
      const hoverDot = hoverG.append('circle').attr('r', 4).attr('fill', 'var(--accent)')

      function sliceVisible() {
        const [a, b] = brushDomain
        return data.filter((d) => d.date >= a && d.date <= b)
      }

      function updateFocus() {
        const vis = sliceVisible()
        if (!vis.length) return

        const x = d3.scaleTime().domain(brushDomain).range([0, innerW])
        const y = d3
          .scaleLinear()
          .domain([
            d3.min(vis, (d) => d.close)! * 0.997,
            d3.max(vis, (d) => d.close)! * 1.003,
          ])
          .nice()
          .range([innerFocusH, 0])

        const line = d3
          .line<{ date: Date; close: number }>()
          .x((d) => x(d.date))
          .y((d) => d.close)
          .defined(() => true)

        gFocusChart.selectAll('path.focus-line').remove()
        gFocusChart
          .append('path')
          .datum(vis)
          .attr('class', 'focus-line')
          .attr('fill', 'none')
          .attr('stroke', 'var(--chart-line)')
          .attr('stroke-width', 2)
          .attr('d', line.y((d) => y(d.close)))

        gxFocus
          .call(d3.axisBottom(x).ticks(width < 520 ? 4 : 8).tickSizeOuter(0))
          .call((g) => g.select('.domain').attr('stroke', 'var(--border)'))
        gyFocus
          .call(
            d3
              .axisLeft(y)
              .ticks(6)
              .tickFormat((v) => d3.format(',.0f')(v as number))
              .tickSizeOuter(0),
          )
          .call((g) => g.select('.domain').attr('stroke', 'var(--border)'))

        focusOverlay.on('mousemove', (event) => {
          const [mx] = d3.pointer(event)
          const x0 = x.invert(mx)
          const idx = bisect(vis, x0, 1)
          const d0 = vis[idx - 1]
          const d1 = vis[idx]
          const d =
            d1 && d0
              ? x0.getTime() - d0.date.getTime() > d1.date.getTime() - x0.getTime()
                ? d1
                : d0
              : d0 ?? d1
          if (!d) return
          hoverG.style('display', null)
          hoverLine
            .attr('x1', x(d.date))
            .attr('x2', x(d.date))
            .attr('y1', 0)
            .attr('y2', innerFocusH)
          hoverDot.attr('cx', x(d.date)).attr('cy', y(d.close))

          const fmt = d3.timeFormat('%b %d, %Y')
          tooltip
            .style('opacity', 1)
            .html(
              `<strong>${fmt(d.date)}</strong><br/>Close: ${d.close.toLocaleString(undefined, {
                maximumFractionDigits: 2,
              })}`,
            )

          const box = container.getBoundingClientRect()
          const tipNode = tooltip.node()!
          const tw = (tipNode as HTMLDivElement).offsetWidth
          const th = (tipNode as HTMLDivElement).offsetHeight
          const px = event.clientX - box.left + 12
          const py = event.clientY - box.top - th - 12
          const clampedX = Math.min(Math.max(8, px), box.width - tw - 8)
          const clampedY = Math.max(8, py)
          tooltip.style('transform', `translate(${clampedX}px,${clampedY}px)`)
        })

        focusOverlay.on('mouseleave', () => {
          hoverG.style('display', 'none')
          tooltip.style('opacity', 0)
        })
      }

      updateFocus()

      return () => {
        tooltip.remove()
      }
    }

    let cleanup: (() => void) | undefined
    const id = requestAnimationFrame(() => {
      cleanup = draw()
    })

    return () => {
      cancelAnimationFrame(id)
      ro.disconnect()
      cleanup?.()
      svg.selectAll('*').remove()
      d3.select(container).selectAll('.sp5-tooltip').remove()
    }
  }, [payload])

  if (loadError) {
    return (
      <div className="sp5-panel sp5-error">
        <p>Could not load <code>/gspc.json</code>.</p>
        <p className="sp5-muted">{loadError}</p>
        <p className="sp5-muted">Run <code>npm run data</code> to generate data, then refresh.</p>
      </div>
    )
  }

  if (!payload) {
    return (
      <div className="sp5-panel">
        <p className="sp5-muted">Loading S&amp;P 500 series…</p>
      </div>
    )
  }

  return (
    <div className="sp5-chart-wrap" ref={wrapRef}>
      <svg className="sp5-svg" role="img" aria-label={`${payload.name} price chart`} />
    </div>
  )
}

.sp5-app {
  text-align: left;
  padding: 28px 24px 48px;
  max-width: 960px;
  margin: 0 auto;
}

.sp5-header h1 {
  margin: 0 0 12px;
  font-size: clamp(28px, 4vw, 40px);
  letter-spacing: -0.04em;
}

.sp5-lede {
  margin: 0;
  max-width: 62ch;
  color: var(--text);
}

.sp5-chart-wrap {
  position: relative;
  margin-top: 28px;
  width: 100%;
}

.sp5-svg {
  display: block;
  width: 100%;
  height: auto;
  color: var(--text-h);
}

.sp5-svg :deep(.tick text) {
  fill: var(--text);
  font-size: 11px;
}

.sp5-svg :deep(.tick line) {
  stroke: var(--border);
}

.sp5-svg :deep(.domain) {
  stroke: var(--border);
}

.sp5-svg :deep(.selection) {
  fill: var(--accent-bg);
  stroke: var(--accent);
  stroke-width: 1px;
}

.sp5-tooltip {
  z-index: 2;
  padding: 8px 10px;
  border-radius: 8px;
  font-size: 13px;
  line-height: 1.35;
  background: var(--bg);
  border: 1px solid var(--border);
  box-shadow: var(--shadow);
  color: var(--text-h);
}

.sp5-footer {
  margin-top: 20px;
  max-width: 70ch;
}

.sp5-footer p {
  margin: 0 0 10px;
}

.sp5-muted {
  color: var(--text);
  font-size: 15px;
}

.sp5-panel {
  padding: 24px;
  border: 1px dashed var(--border);
  border-radius: 12px;
  margin-top: 24px;
}

.sp5-error {
  border-color: var(--accent-border);
}

:root {
  --chart-line: #2563eb;
  --chart-muted: color-mix(in srgb, var(--text) 45%, var(--border));
}

@media (prefers-color-scheme: dark) {
  :root {
    --chart-line: #93c5fd;
  }
}

